import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });
});

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions with optional limit and before while stripping extra fields and rejecting malformed values', () => {
    const bare = validateMessage({type: 'list_sessions', userId: 'spoof'});
    const paged = validateMessage({
      type: 'list_sessions',
      limit: 0,
      before: {sessionId: 's1', updatedAt: '2026-04-10T11:00:00.000Z', extra: true},
    });
    const numericCursor = validateMessage({
      type: 'list_sessions',
      limit: 25,
      before: {sessionId: 'x'.repeat(128), updatedAt: 1_700_000_000_000},
    });
    const rejected = [
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', limit: '10'}),
      validateMessage({type: 'list_sessions', before: null}),
      validateMessage({type: 'list_sessions', before: []}),
      validateMessage({type: 'list_sessions', before: {sessionId: '', updatedAt: 0}}),
      validateMessage({type: 'list_sessions', before: {sessionId: 'x'.repeat(129), updatedAt: 0}}),
      validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: 'not-a-date'}}),
      validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: true}}),
    ].map(outcome => outcome.valid);

    expect({bare, paged, numericCursor, rejected}).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      paged: {
        valid: true,
        data: {type: 'list_sessions', limit: 0, before: {sessionId: 's1', updatedAt: '2026-04-10T11:00:00.000Z'}},
      },
      numericCursor: {
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 25,
          before: {sessionId: 'x'.repeat(128), updatedAt: 1_700_000_000_000},
        },
      },
      rejected: Array(9).fill(false),
    });
  });
});

