import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  if (message.type === 'user_message') return validateUserMessage(message);
  if (message.type === 'ping') return validatePingMessage(message);
  if (message.type === 'list_sessions') return validateListSessions(message);
  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have a string content field'};
  }

  const trimmed = message.content.trim();
  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content exceeds maximum length of ${MAX_CONTENT_LENGTH}`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessions(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && !isValidLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (message.before === undefined) {
    return {valid: true, data: buildListSessionsFrame(message.limit as number | undefined, undefined)};
  }

  const before = parseBeforeCursor(message.before);
  if (before === null) {
    return {valid: false, error: 'list_sessions before must have a valid sessionId and updatedAt'};
  }

  return {valid: true, data: buildListSessionsFrame(message.limit as number | undefined, before)};
}

function isValidLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function buildListSessionsFrame(
  limit: number | undefined,
  before: ListSessionsMessage['before']
): ListSessionsMessage {
  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) frame.limit = limit;
  if (before !== undefined) frame.before = before;
  return frame;
}

function parseBeforeCursor(candidate: unknown): NonNullable<ListSessionsMessage['before']> | null {
  if (typeof candidate !== 'object' || candidate === null || Array.isArray(candidate)) return null;
  const cursor = candidate as Record<string, unknown>;
  if (!isValidSessionId(cursor.sessionId) || !isValidTimestamp(cursor.updatedAt)) return null;
  return {sessionId: cursor.sessionId, updatedAt: cursor.updatedAt};
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidTimestamp(updatedAt: unknown): updatedAt is string | number {
  const isPrimitive = typeof updatedAt === 'string' || typeof updatedAt === 'number';
  return isPrimitive && Number.isFinite(new Date(updatedAt).getTime());
}

